script:
country_event = { # Cyberization - First event
	id = cyber.1
	hide_window = yes
	is_triggered_only = yes

	immediate = {
		if = { # Hives get their own special situation
			limit = {
				is_hive_empire = yes
			}
			start_situation = {
				type = situation_cyberization_hive
				target = root
			}
		}
		else = {
			start_situation = {
				type = situation_cyberization
				target = root
			}
		}
	}
}

